const e={render(){const t=document.createElement("div");return t.innerHTML='\n      <div style="max-width:800px;margin:0 auto;padding:40px 24px;font-family:sans-serif;" data-edit-path="div.0">\n        <h2 style="font-size:1.8rem;color:#7B2FBE;margin:0 0 8px;" data-edit-path="div.0/h2.0">Apps Script: doPost Handler</h2>\n        <p style="color:#555;margin:0 0 20px;" data-edit-path="div.0/p.0">This script runs every time something POSTs to your URL. It reads the JSON payload and writes one row to your sheet.</p>\n        <div style="background:#0D0D0D;border-radius:12px;padding:24px;margin-bottom:20px;overflow-x:auto;" data-edit-path="div.0/div.0">\n          <pre style="color:#00D4AA;font-family:monospace;font-size:0.85rem;line-height:1.8;margin:0;" data-edit-path="div.0/div.0/pre.0">function doPost(e) {\n  const sheet = SpreadsheetApp\n    .getActiveSpreadsheet().getActiveSheet();\n  const data = JSON.parse(e.postData.contents);\n\n  sheet.appendRow([\n    data.date, data.title, data.caption,\n    data.hashtags, data.image_url,\n    data.source, data.source_url,\n    data.quote, data.status || "pending"\n  ]);\n\n  return ContentService\n    .createTextOutput(JSON.stringify({ success: true }))\n    .setMimeType(ContentService.MimeType.JSON);\n}</pre>\n        </div>\n        <div style="background:#fff3cd;border-left:4px solid #F5A623;border-radius:8px;padding:16px 20px;" data-edit-path="div.0/div.1">\n          <strong data-edit-path="div.0/div.1/strong.0">⚠️ Important:</strong> Google Apps Script redirects POST requests. Your Python code must follow the redirect: POST to capture the Location header, then GET that URL. Skip this step and your POST silently fails.\n        </div>\n      </div>',t}};export{e as slide};
